package org.eclipse.rdf4j.query.algebra.helpers;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Set;

import org.eclipse.rdf4j.query.algebra.Exists;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Union;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class QueryAlgebraBindingAnalysisScopeIdentityTest {

	@Test
	void subqueryScopeSurvivesInvalidationWhileJoinFactsAreRefreshed() {
		Union union = new Union(pattern("first"), pattern("second"));
		Join join = new Join(pattern("before"), union);
		QueryRoot root = new QueryRoot(new Projection(join));

		assertScopeSurvivesJoinChange(root, join, union);
	}

	@Test
	void existsScopeSurvivesInvalidationWhileJoinFactsAreRefreshed() {
		Union union = new Union(pattern("first"), pattern("second"));
		Join join = new Join(pattern("before"), union);
		QueryRoot root = new QueryRoot(new Filter(new SingletonSet(), new Exists(join)));

		assertScopeSurvivesJoinChange(root, join, union);
	}

	@Test
	void replacementScopeGetsFreshIdentityWithoutRenumberingUnchangedScope() {
		Projection first = new Projection(new SingletonSet());
		Projection second = new Projection(new SingletonSet());
		Union union = new Union(first, second);
		QueryRoot root = new QueryRoot(union);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(root, Set.of());
		long firstIdentity = analysis.contextAt(first.getArg()).scopeIdentity();
		long secondIdentity = analysis.contextAt(second.getArg()).scopeIdentity();
		assertThat(secondIdentity).isNotEqualTo(firstIdentity);

		Projection replacement = first.clone();
		union.setLeftArg(replacement);
		analysis.invalidate(root);

		long replacementIdentity = analysis.contextAt(replacement.getArg()).scopeIdentity();
		assertThat(replacementIdentity).isNotIn(firstIdentity, secondIdentity, analysis.rootContext().scopeIdentity());
		assertThat(analysis.contextAt(second.getArg()).scopeIdentity()).isEqualTo(secondIdentity);

		analysis.invalidate();
		assertThat(analysis.contextAt(replacement.getArg()).scopeIdentity()).isEqualTo(replacementIdentity);
		assertThat(analysis.contextAt(second.getArg()).scopeIdentity()).isEqualTo(secondIdentity);
	}

	@Test
	void movedOperandUsesItsNewEnclosingScopeAndBindingFacts() {
		StatementPattern moved = pattern("moved");
		Join firstJoin = new Join(pattern("firstPrefix"), moved);
		Join secondJoin = new Join(pattern("secondPrefix"), new SingletonSet());
		Projection first = new Projection(firstJoin);
		Projection second = new Projection(secondJoin);
		QueryRoot root = new QueryRoot(new Union(first, second));
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(root, Set.of());
		var originalInput = analysis.contextAt(moved);
		long secondIdentity = analysis.contextAt(secondJoin.getRightArg()).scopeIdentity();
		assertThat(originalInput.guaranteedNames()).contains("firstPrefix").doesNotContain("secondPrefix");
		assertThat(secondIdentity).isNotEqualTo(originalInput.scopeIdentity());

		firstJoin.setRightArg(new SingletonSet());
		secondJoin.setRightArg(moved);
		analysis.invalidate();

		var movedInput = analysis.contextAt(moved);
		assertThat(movedInput).isNotSameAs(originalInput);
		assertThat(movedInput.scopeIdentity()).isEqualTo(secondIdentity).isNotEqualTo(originalInput.scopeIdentity());
		assertThat(movedInput.guaranteedNames()).contains("secondPrefix").doesNotContain("firstPrefix");
		assertThat(analysis.contextAt(firstJoin).scopeIdentity()).isEqualTo(originalInput.scopeIdentity());
	}

	@Test
	void removingUnionScopeRestoresTheUnchangedEnclosingScope() {
		Union union = new Union(pattern("first"), pattern("second"));
		union.setVariableScopeChange(true);
		Projection subquery = new Projection(union);
		QueryRoot root = new QueryRoot(subquery);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(root, Set.of());
		long enclosingIdentity = analysis.contextAt(union).scopeIdentity();
		long unionIdentity = analysis.contextAt(union.getLeftArg()).scopeIdentity();
		assertThat(unionIdentity).isNotEqualTo(enclosingIdentity);

		union.setVariableScopeChange(false);
		analysis.invalidate(root);

		assertThat(analysis.contextAt(union.getLeftArg()).scopeIdentity()).isEqualTo(enclosingIdentity);
		assertThat(analysis.contextAt(union.getRightArg()).scopeIdentity()).isEqualTo(enclosingIdentity);
	}

	private static void assertScopeSurvivesJoinChange(TupleExpr root, Join join, Union union) {
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(root, Set.of());
		var firstInput = analysis.contextAt(union.getLeftArg());
		var oldFacts = analysis.outputFacts(join);
		assertThat(firstInput.scopeIdentity()).isNotEqualTo(analysis.rootContext().scopeIdentity());
		assertThat(firstInput.guaranteedNames()).contains("before").doesNotContain("after");

		join.setLeftArg(pattern("after"));
		analysis.invalidate(root);

		var secondInput = analysis.contextAt(union.getRightArg());
		assertThat(secondInput.scopeIdentity())
				.as("optimizing an earlier operand must not disconnect the next UNION arm from the same scope")
				.isEqualTo(firstInput.scopeIdentity());
		assertThat(secondInput).isNotSameAs(firstInput);
		assertThat(secondInput.guaranteedNames()).contains("after").doesNotContain("before");
		assertThat(firstInput.guaranteedNames()).contains("before").doesNotContain("after");
		var refreshedFacts = analysis.outputFacts(join);
		assertThat(refreshedFacts).isNotSameAs(oldFacts);
		assertThat(refreshedFacts.guaranteedOutputs()).contains("after").doesNotContain("before");
	}

	private static StatementPattern pattern(String object) {
		return new StatementPattern(Var.of("s"), Var.of("p"), Var.of(object));
	}
}
